def choose_move(observation):
    def clamp_step(v):
        return -1 if v < -1 else (1 if v > 1 else v)

    def sign(a, b):
        return 0 if a == b else (1 if a > b else -1)

    def get_xy(value):
        if isinstance(value, dict):
            if "x" in value and "y" in value:
                return [value.get("x", 0), value.get("y", 0)]
            if "row" in value and "col" in value:
                return [value.get("col", 0), value.get("row", 0)]
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            return [value[0], value[1]]
        return [0, 0]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(src, dst):
        return [sign(dst[0], src[0]), sign(dst[1], src[1])]

    def step_away(src, dst):
        return [sign(src[0], dst[0]), sign(src[1], dst[1])]

    def best_by_distance(points, ref, reverse=False):
        best = None
        best_score = None
        for p in points or []:
            q = get_xy(p)
            score = manhattan(q, ref)
            if best is None or (reverse and score > best_score) or ((not reverse) and score < best_score):
                best = q
                best_score = score
        return best

